import{c as t,S as a,j as o,m as r}from"./chunks/framework.C68YPdek.js";const p=JSON.parse('{"title":"Plugins and modules","description":"","frontmatter":{},"headers":[],"relativePath":"developer/architecture/plugins-and-modules.md","filePath":"developer/architecture/plugins-and-modules.md"}'),d={name:"developer/architecture/plugins-and-modules.md"};function s(n,e,i,h,l,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="plugins-and-modules" tabindex="-1">Plugins and modules <a class="header-anchor" href="#plugins-and-modules" aria-label="Permalink to “Plugins and modules”">​</a></h1><p>Two ways to extend what a program can do or show: <strong>plugins</strong> show a run, and <strong>modules</strong> give a program libraries to import. Checked against the repositories on 28 November 2026.</p><h2 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to “Plugins”">​</a></h2><p><a href="https://github.com/source-academy/plugins" target="_blank" rel="noreferrer"><code>plugins</code></a> is a monorepo of the packages that tools are made of, in three groups under <code>src</code>: <code>common</code> (the protocol: types and the id in the plugin directory), <code>runner</code> (what an evaluator uses: a base class and the streaming of steps) and <code>web</code> (what the browser loads: a host plugin and the view, which contributes a side-content tab). Packages are released with Changesets, and the web bundles are built and deployed to GitHub Pages; the entries in the <a href="./directories">plugin directory</a> point to them.</p><p>The plugins today:</p><table tabindex="0"><thead><tr><th>Plugin</th><th>What it shows</th></tr></thead><tbody><tr><td>Stepper</td><td>Substitution steps; one plugin for several languages, with a rules profile from the evaluator</td></tr><tr><td>E-Stepper</td><td>The program with its environment frames and heap, step by step</td></tr><tr><td>Data Visualizer</td><td>Data structures, over a channel of its own</td></tr><tr><td>CSE machine</td><td>The control, the stash and the environments, for languages that share the environment model</td></tr></tbody></table><p>A plugin is loaded when an evaluator calls <code>hostLoadPlugin(id)</code>; the host fetches the bundle from the plugin directory&#39;s URL, and the plugin registers its tab with the tab service. What the host offers a plugin beyond the tab service (editor highlighting, today) is the host contract in <code>common-tabs</code>. The guide <a href="./../writing-a-visualizer-plugin">Writing a visualizer plugin</a> covers all of this.</p><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to “Modules”">​</a></h2><p><a href="https://github.com/source-academy/modules" target="_blank" rel="noreferrer"><code>modules</code></a> holds the default <strong>bundles</strong> (libraries a program imports, such as <code>rune</code>, <code>curve</code>, <code>plotly</code>, <code>midi</code> and <code>repl</code>) and their <strong>tabs</strong> (the side-content tab that a bundle can contribute, for example to draw a rune), with the documentation for them and the tooling to build them. Its layout is <code>src/bundles</code>, <code>src/tabs</code>, a <code>devserver</code>, a documentation server (<code>docs</code>, published at <a href="https://source-academy.github.io/modules/documentation" target="_blank" rel="noreferrer">https://source-academy.github.io/modules/documentation</a>) and a developer documentation site (<a href="https://source-academy.github.io/modules/devdocs" target="_blank" rel="noreferrer">https://source-academy.github.io/modules/devdocs</a>).</p><p>The frontend finds the modules through the modules directory (<code>modules.json</code>) and loads them with the module loader plugin; a module talks to the evaluator through the <a href="./conductor">Conductor</a> module interface.</p><h2 id="the-difference" tabindex="-1">The difference <a class="header-anchor" href="#the-difference" aria-label="Permalink to “The difference”">​</a></h2><p>A plugin is chosen by the evaluator and shows the run; a module is imported by the program and is part of what the program does. Both are fetched at run time from GitHub Pages.</p>',12)])])}const m=t(d,[["render",s]]);export{p as __pageData,m as default};
